      if($pending.Schema -ne 1 -or $pending.LabId -ne $labId -or $pending.Host -ne $env:COMPUTERNAME -or $pending.Run -notmatch '^[a-f0-9]{32}$' -or $pending.DomainDN -ne $d.DistinguishedName){throw 'Invalid prepare intent'}
