    $g=Get-GPO -Guid $id
    if(-not $g.DisplayName.StartsWith('LabEx-'+$m.Run+'-')){throw 'GPO outside lesson namespace'}
  }
  if($type -eq 'ZONE'){
    $z=Get-DnsServerZone -Name $id
    if($id -ne $m.Zone -and $id -ne '2.0.192.in-addr.arpa'){throw 'DNS zone outside lesson namespace'}
