}
function New-SrvUser([string]$suffix){
  if($suffix -notin @('learner','delegate','control')){throw 'Unexpected user role'}
  $m=Get-SrvContext;$ou=New-SrvOU 'Users';$sam='lx'+$m.Run.Substring(0,8)+$suffix
