  if(@($right).Count -ne 1){throw 'Cannot resolve Reset Password extended right'}
  return [guid]$right.rightsGuid
}
$m=Get-SrvContext;$g=New-SrvGroup 'Global';$dn='OU=Users,'+$m.RootDN
$acl=Get-Acl ('AD:\'+$dn);$right=Get-SrvResetRight
$user=Get-ADObject -Identity ('CN=User,'+(Get-ADRootDSE).schemaNamingContext) -Properties schemaIDGUID
$rule=[DirectoryServices.ActiveDirectoryAccessRule]::new($g.SID,[DirectoryServices.ActiveDirectoryRights]::ExtendedRight,[Security.AccessControl.AccessControlType]::Allow,$right,[DirectoryServices.ActiveDirectorySecurityInheritance]::Descendents,[guid]::new([byte[]]$user.schemaIDGUID))
